  type(factor_analysis) :: fa
  type(gaussian_random_projection) :: projection
  type(sparse_random_projection) :: sparse_projection
  type(huber_regressor) :: huber
  type(ransac_regressor) :: ransac
  type(poisson_regressor) :: poisson
  type(gamma_regressor) :: gamma
  type(tweedie_regressor) :: tweedie
  type(mean_shift) :: ms
  type(affinity_propagation) :: ap
  type(spectral_clustering) :: spectral
  type(spectral_embedding) :: embedding
  type(kernel_density) :: density
  type(index_split), allocatable :: folds(:)
  real(dp) :: x(4,2),y(4)
  real(dp), allocatable :: z(:,:),pred(:)
  integer, allocatable :: optics_clusters(:,:)
  integer, allocatable :: labels(:)
  character(32) :: mode
  sne%perplexity=2; sne%init="random"; sne%max_iter=250
  lv_case%n_neighbors=3
  do lv_i=1,8
    do lv_j=1,3
      lv_x(lv_i,lv_j)=sin(.731_dp*lv_i*lv_j)+cos(.213_dp*lv_i*lv_i+.191_dp*lv_j)
    end do
  end do
  mt_y=1
  sp_projection%max_iter=3; sp_dictionary%max_iter=3
  angle_cv%cv=2; angle_sparse_cv%cv=2
  elimination_cv%cv=2
  seq%cv=2
  x=1; y=1; call get_command_argument(1,mode)
  hd_x(:,1)=[-3._dp,-2._dp,-1._dp,1._dp,2._dp,3._dp]
  hd_x(:,2)=[0._dp,1._dp,-1._dp,2._dp,0._dp,1._dp]
  hd_dist=reshape([0._dp,1._dp,3._dp,4._dp,1._dp,0._dp,2._dp,3._dp, &
    3._dp,2._dp,0._dp,1._dp,4._dp,3._dp,1._dp,0._dp],[4,4])
  hd_case%min_cluster_size=2; hd_case%min_samples=2
  bg_x(:,1)=[-3._dp,-2._dp,-1._dp,1._dp,2._dp,3._dp]
  bg_x(:,2)=[0._dp,1._dp,-1._dp,2._dp,0._dp,1._dp]
  bg_case%n_components=2; bg_case%max_iter=3
  bc_x=reshape([12._dp,13._dp,2._dp,3._dp,12._dp,14._dp,2._dp,4._dp, &
    2._dp,3._dp,15._dp,16._dp,2._dp,4._dp,16._dp,18._dp],[4,4])
  bc_co%n_clusters=2; bc_co%n_init=1
  bc_bi%n_clusters=2; bc_bi%n_components=2; bc_bi%n_best=1; bc_bi%n_init=1
  mb_case%n_clusters=2; mb_case%max_iter=2; mb_case%batch_size=6
  bisect_case%n_clusters=2
  rbm_case%n_components=2; rbm_case%n_iter=1; rbm_case%batch_size=3; rbm_x=.5_dp
  lda_case%n_components=2; lda_case%max_iter=1; lda_case%batch_size=3; lda_x=.5_dp
  mbd_case%n_components=2; mbd_case%max_iter=1; mbd_case%batch_size=3
  mbd_case%fit_algorithm='cd'; mbd_case%transform_algorithm='lasso_cd'
  mbsp_case%n_components=2; mbsp_case%max_iter=1; mbsp_case%method='cd'; mbd_x=1
  mbn_case%n_components=2; mbn_case%max_iter=1; mbn_case%init='random'
  mbn_x=.5_dp; mbn_w=1; mbn_h=1
  mtcv_case%cv=2; mtcv_case%n_alphas=3; mtcv_case%max_iter=20
  mtlc_case%cv=2; mtlc_case%n_alphas=3; mtlc_case%max_iter=20
  mtcv_x(:,1)=[-3._dp,-2._dp,-1._dp,1._dp,2._dp,3._dp]
  mtcv_x(:,2)=[0._dp,1._dp,2._dp,0._dp,-1._dp,-2._dp]; mtcv_x(:,3)=1
  mtcv_y(:,1)=mtcv_x(:,1)+.5_dp*mtcv_x(:,2); mtcv_y(:,2)=2*mtcv_x(:,1)
  ompcv%cv=2; ompcv%max_iter=2; ompcv_x=mtcv_x
  ompcv_y=mtcv_y(:,1)
  uv_x(:,1)=[-1._dp,-1._dp,1._dp,1._dp]; uv_x(:,2)=[-1._dp,1._dp,-1._dp,1._dp]; uv_x(:,3)=0
  uv_y=[-1,-1,1,1]; uv_scores=[1._dp,2._dp,3._dp]; uv_pvalues=[.01_dp,.04_dp,.8_dp]
  mi_x(:,1)=[0._dp,1._dp,2._dp,3._dp,4._dp,5._dp]
  mi_x(:,2)=[0._dp,0._dp,1._dp,1._dp,2._dp,2._dp]; mi_x(:,3)=1
  mi_y=mi_x(:,1); mi_labels=[-1,-1,-1,2,2,2]
  select case(trim(mode))
  case('te_multiclass_fractional')
    te_case%target_type='multiclass'; call te_case%fit(te_x,te_y+.2_dp)
  case('te_unfitted')
    te_z=te_case%transform(te_x)
  case('te_empty_rows')
    call te_case%fit(te_x(:0,:),te_y(:0))
  case('te_empty_features')
    call te_case%fit(te_x(:,:0),te_y)
  case('te_infinity')
    te_x(1,1)=ieee_value(0._dp,ieee_positive_inf); call te_case%fit(te_x,te_y)
  case('te_target_length')
    call te_case%fit(te_x,te_y(:3))
  case('te_target_nan')
    te_y(1)=ieee_value(0._dp,ieee_quiet_nan); call te_case%fit(te_x,te_y)
  case('te_target_range')
    te_y(1)=huge(1._dp); call te_case%fit(te_x,te_y)
  case('te_target_type')
    te_case%target_type='invalid'; call te_case%fit(te_x,te_y)
  case('te_smooth_nan')
    te_case%smooth=ieee_value(0._dp,ieee_quiet_nan); call te_case%fit(te_x,te_y)
  case('te_smooth_negative')
    te_case%smooth=-1; call te_case%fit(te_x,te_y)
  case('te_cv_one')
    te_case%cv=1; call te_case%fit(te_x,te_y)
  case('te_seed_negative')
    te_case%random_state=-1; call te_case%fit(te_x,te_y)
  case('te_multiclass_two')
    te_case%target_type='multiclass'; call te_case%fit(te_x,te_y)
  case('te_category_width')
    allocate(te_case%categories(2)); call te_case%fit(te_x,te_y)
  case('te_category_unallocated')
    allocate(te_case%categories(1)); call te_case%fit(te_x,te_y)
  case('te_category_empty')
    allocate(te_case%categories(1)); te_case%categories(1)%values=[real(dp)::]
    call te_case%fit(te_x,te_y)
  case('te_category_inf')
    allocate(te_case%categories(1)); te_case%categories(1)%values=[ieee_value(0._dp,ieee_positive_inf)]
    call te_case%fit(te_x,te_y)
  case('te_category_duplicate')
    allocate(te_case%categories(1)); te_case%categories(1)%values=[0._dp,0._dp]
    call te_case%fit(te_x,te_y)
  case('te_category_nan_order')
    allocate(te_case%categories(1))
    te_case%categories(1)%values=[ieee_value(0._dp,ieee_quiet_nan),0._dp]; call te_case%fit(te_x,te_y)
  case('te_category_sort')
    allocate(te_case%categories(1)); te_case%categories(1)%values=[1._dp,0._dp]
    call te_case%fit(te_x,te_y)
  case('te_query_width')
    call te_case%fit(te_x,te_y); te_z=te_case%transform(spread(te_y,2,2))
  case('te_query_empty')
    call te_case%fit(te_x,te_y); te_z=te_case%transform(te_x(:0,:))
  case('te_query_inf')
    call te_case%fit(te_x,te_y); te_x(1,1)=ieee_value(0._dp,ieee_positive_inf)
    te_z=te_case%transform(te_x)
  case('te_cv_large')
    te_case%cv=5; te_z=te_case%fit_transform(te_x,te_y)
  case('te_cv_class_counts')
    te_case%cv=3; te_z=te_case%fit_transform(te_x,te_y)
  case('te_cv_fractional_class')
    te_case%target_type='binary'; te_case%cv=2
    te_z=te_case%fit_transform(te_x,te_y+.2_dp)
  case('stk_prefit_splits')
    call wt_clf%fit(wt_x,wt_y)
    st_bases(1)%name='tree'
    allocate(st_bases(1)%estimator,source=wt_clf)
    st_c%cv=2
    st_c%prefit=.true.
    call st_c%fit(wt_x,wt_y,st_bases(:1),splits=st_plans)
  case('stk_prefit_no_features')
    call wt_clf%fit(wt_x,[0,0,0,0])
    st_bases(1)%name='tree'
    allocate(st_bases(1)%estimator,source=wt_clf)
    st_c%cv=2
    st_c%prefit=.true.
    call st_c%fit(wt_x,wt_y,st_bases(:1))
  case('stk_fold_decision_missing')
