  case('cc_logistic_zero_fit')
    cc_case%cv=3
    cc_weights=0
    call cc_case%fit(cc_x,cc_y,cc_lr,cc_weights)
  case('st_undefined_base')
    st_x=0
    call st_case%fit(st_x,st_y,st_nb)

  case('cc_method')
    cc_case%cv=3
    cc_case%method='unknown'
    call cc_case%fit(cc_x,cc_y,cc_nb)
  case('cc_cv_zero')
    cc_case%cv=3
    cc_case%cv=0
    call cc_case%fit(cc_x,cc_y,cc_nb)
  case('cc_cv_one')
    cc_case%cv=3
    cc_case%cv=1
    call cc_case%fit(cc_x,cc_y,cc_nb)
  case('cc_cv_large')
    cc_case%cv=3
    cc_case%cv=7
    call cc_case%fit(cc_x,cc_y,cc_nb)
  case('cc_cv_class')
    cc_case%cv=3
    cc_case%cv=4
    call cc_case%fit(cc_x,cc_y,cc_nb)
  case('cc_single_class')
    cc_case%cv=3
    cc_y=0
    call cc_case%fit(cc_x,cc_y,cc_nb)
  case('cc_nan')
    cc_case%cv=3
