    call st_case%fit(st_x,st_y,st_nb)
  case('st_threshold_negative')
    st_case%threshold=-.1_dp
    call st_case%fit(st_x,st_y,st_nb)
  case('st_threshold_one')
    st_case%threshold=1
    call st_case%fit(st_x,st_y,st_nb)
  case('st_criterion')
    st_case%criterion='invalid'
    call st_case%fit(st_x,st_y,st_nb)
  case('st_k_zero')
    st_case%k_best=0
    call st_case%fit(st_x,st_y,st_nb)
  case('st_k_negative')
    st_case%k_best=-1
    call st_case%fit(st_x,st_y,st_nb)
  case('st_max_negative')
    st_case%max_iter=-2
    call st_case%fit(st_x,st_y,st_nb)
  case('st_unlabeled')
    st_y=-1
    call st_case%fit(st_x,st_y,st_nb)
  case('st_nan')
    st_x(1,1)=ieee_value(0._dp,ieee_quiet_nan)
    call st_case%fit(st_x,st_y,st_nb)
  case('st_length')
    call st_case%fit(st_x,st_y(:3),st_nb)
  case('st_empty')
    call st_case%fit(st_x(:0,:),st_y(:0),st_nb)
  case('st_unsupported')
    call st_case%fit(st_x,st_y,1)
  case('st_unfit_proba')
    st_prob=st_case%predict_proba(st_x)
  case('st_unfit_decision')
    st_prob=st_case%decision_function(st_x)
  case('st_features')
    call st_case%fit(st_x,st_y,st_nb)
    st_prob=st_case%predict_proba(spread(st_x(:,1),2,2))
  case('st_query_nan')
    call st_case%fit(st_x,st_y,st_nb)
    st_x(1,1)=ieee_value(0._dp,ieee_quiet_nan)
    st_prob=st_case%predict_proba(st_x)
  case('st_no_decision')
    call st_case%fit(st_x,st_y,st_nb)
    st_prob=st_case%decision_function(st_x)
  case('st_no_log_proba')
    st_knn%n_neighbors=1
    call st_case%fit(st_x,st_y,st_knn)
    st_prob=st_case%predict_log_proba(st_x)

  case('rk_roc_length')
    call roc_curve(rk_y(:3),rk_s,rk_a,rk_b,rk_c)
  case('rk_roc_empty')
    call roc_curve(rk_y(:0),rk_s(:0),rk_a,rk_b,rk_c)
  case('rk_pr_length')
    call precision_recall_curve(rk_y(:3),rk_s,rk_a,rk_b,rk_c)
  case('rk_pr_empty')
    call precision_recall_curve(rk_y(:0),rk_s(:0),rk_a,rk_b,rk_c)
  case('rk_det_length')
    call det_curve(rk_y(:3),rk_s,rk_a,rk_b,rk_c)
  case('rk_det_empty')
    call det_curve(rk_y(:0),rk_s(:0),rk_a,rk_b,rk_c)
  case('rk_roc_nan')
