  case('mt_mix_high')
    mt%l1_ratio=2; call mt%fit(x,mt_y)
  case('mt_nan_mix')
    mt%l1_ratio=ieee_value(0._dp,ieee_quiet_nan); call mt%fit(x,mt_y)
  case('mt_tol')
