  case('rc_alpha')
    labels=[-3,-3,9,9]; rc%alpha=-1; call rc%fit(x,labels)
  case('rc_nan_alpha')
    labels=[-3,-3,9,9]; rc%alpha=ieee_value(0._dp,ieee_quiet_nan); call rc%fit(x,labels)
  case('rc_targets')
    labels=[-3,-3,9,9]; call rc%fit(x,[1,2])
  case('rc_single')
    labels=[-3,-3,9,9]; call rc%fit(x,[1,1,1,1])
  case('rc_sample_shape')
    labels=[-3,-3,9,9]; call rc%fit(x,labels,sample_weight=[1._dp,1._dp])
  case('rc_sample_negative')
    labels=[-3,-3,9,9]; call rc%fit(x,labels,sample_weight=[1._dp,-1._dp,1._dp,1._dp])
  case('rc_sample_nan')
    labels=[-3,-3,9,9]; y(1)=ieee_value(0._dp,ieee_quiet_nan); call rc%fit(x,labels,sample_weight=y)
  case('rc_sample_zero')
    labels=[-3,-3,9,9]; call rc%fit(x,labels,sample_weight=0*y)
  case('rc_class_shape')
    labels=[-3,-3,9,9]; call rc%fit(x,labels,class_weight=[1._dp])
  case('rc_class_negative')
    labels=[-3,-3,9,9]; call rc%fit(x,labels,class_weight=[1._dp,-1._dp])
  case('rc_class_nan')
    labels=[-3,-3,9,9]; y(1)=ieee_value(0._dp,ieee_quiet_nan); call rc%fit(x,labels,class_weight=y(:2))
  case('rc_class_zero')
    labels=[-3,-3,9,9]; call rc%fit(x,labels,class_weight=[0._dp,0._dp])
  case('rc_class_conflict')
    labels=[-3,-3,9,9]; rc%class_weight_balanced=.true.; call rc%fit(x,labels,class_weight=[1._dp,1._dp])
  case('rc_unfitted')
    labels=[-3,-3,9,9]; labels=rc%predict(x)
  case('rc_unfitted_decision')
    labels=[-3,-3,9,9]; z=rc%decision_function(x)
  case('rc_features')
    labels=[-3,-3,9,9]; call rc%fit(x,labels); z=rc%decision_function(x(:,:1))
  case('rc_empty')
    labels=[-3,-3,9,9]; call rc%fit(x(:0,:),labels(:0))
  case('rc_nan_x')
    labels=[-3,-3,9,9]; x(1,1)=ieee_value(0._dp,ieee_quiet_nan); call rc%fit(x,labels)
  case('rc_nan_query')
    labels=[-3,-3,9,9]; call rc%fit(x,labels); x(1,1)=ieee_value(0._dp,ieee_quiet_nan); z=rc%decision_function(x)
  case('rc_query_empty')
    labels=[-3,-3,9,9]; call rc%fit(x,labels); z=rc%decision_function(x(:0,:))
