  case('rc_cv_negative_alpha')
    labels=[-3,-3,9,9]; rc_cv%alphas=[-1._dp,1._dp]; call rc_cv%fit(x,labels)
  case('rc_cv_nan_alpha')
    labels=[-3,-3,9,9]; rc_cv%alphas=[ieee_value(0._dp,ieee_quiet_nan)]; call rc_cv%fit(x,labels)
  case('rc_cv_one_positive')
    labels=[-3,-3,9,9]; call rc_cv%fit(x,labels,sample_weight=[1._dp,0._dp,0._dp,0._dp])
  case('rc_cv_single')
    labels=[-3,-3,9,9]; call rc_cv%fit(x,[1,1,1,1])
  case('rc_cv_unfitted')
    labels=[-3,-3,9,9]; labels=rc_cv%predict(x)
  case('rc_cv_sample_shape')
    labels=[-3,-3,9,9]; call rc_cv%fit(x,labels,sample_weight=[1._dp,1._dp])

  case('gbc_estimators')
