  case('gbc_single_class')
    labels=[-3,-3,9,9]; call boost_class%fit(x,[1,1,1,1])
  case('gbc_exponential_multiclass')
    labels=[-3,-3,9,9]; boost_class%loss='exponential'; call boost_class%fit(x,[1,2,3,3])
