    model_birch%n_clusters=-1; call model_birch%fit(x)
  case('birch_empty')
    call model_birch%fit(x(:0,:))
  case('birch_x_nan')
    x(1,1)=ieee_value(0._dp,ieee_quiet_nan); call model_birch%fit(x)
