  case('optics_diagonal')
    model%min_samples=2; model%metric='precomputed'; z=x(:2,:); call model%fit(z)
  case('optics_order')
    model%min_samples=2; labels=cluster_optics_dbscan(y,y,[1,1,3,4],1._dp)
  case('optics_order_range')
