  case('ica_rank'); call ica%fit(x)
  case('ica_init_shape'); ica%whiten='none'; ica%w_init=reshape([1._dp],[1,1]); call ica%fit(x)
  case('ica_init_singular'); ica%whiten='none'; ica%w_init=x(:2,:); call ica%fit(x)
  case default; error stop 'unknown validation mode'
  end select
  print *, 'ERROR: invalid input was accepted'
contains
  function pi_score(features,rows,sample_weight) result(value)
    real(dp), intent(in) :: features(:,:)
    integer, intent(in) :: rows(:)
    real(dp), intent(in), optional :: sample_weight(:)
    real(dp) :: value
    value=0
  end function
  function pi_scores(features,rows,sample_weight) result(values)
    real(dp), intent(in) :: features(:,:)
    integer, intent(in) :: rows(:)
    real(dp), intent(in), optional :: sample_weight(:)
    real(dp), allocatable :: values(:)
    pi_calls=pi_calls+1
    values=[0._dp]
    if(pi_bad==1) values=[real(dp) ::]
    if(pi_bad==2.and.pi_calls>1) values=[0._dp,0._dp]
  end function
  function pd_predict(features) result(values)
    real(dp), intent(in) :: features(:,:)
    real(dp), allocatable :: values(:,:)
    integer :: rows,outputs
    pd_calls=pd_calls+1; rows=size(features,1); outputs=1
    if(pd_bad==1) rows=rows-1
    if(pd_bad==2) outputs=0
    if(pd_bad==3.and.pd_calls>1) outputs=2
    allocate(values(rows,outputs)); values=0
  end function
end program
